import {empty,validate,change,archive,browse,stages} from './model.mjs';
import {parseBackup,mergeBackup,MAX_IMPORT_BYTES} from './import.mjs';
export function mount({container,state,setState,search='',signal,theme='dark'}){
 const root=container.shadowRoot||container.attachShadow({mode:'open'});let data,disposed=false,selected=null,editing=null,generation=0,ownership='',stage='',archived=false;const urls=new Set();
 let failure='';try{data=state===undefined?empty():validate(state);}catch(e){failure='Stored projects could not be opened and have not been overwritten. '+e.message;}
 root.innerHTML=`<div class="project-shell"><header><p class="eyebrow">YOUR NEXT WORLD STARTS HERE</p><h2>Project browser</h2><p>Ideas you own. Work you follow. One place to see what comes next.</p><div class="toolbar"><button id="new">New project</button><button id="export">Export projects</button><label class="import">Import backup<input id="import" type="file" accept="application/json,.json"></label></div></header><p id="notice" role="status"></p><div class="filters"><label>Project ownership<select id="ownership" aria-label="Project ownership"><option value="">All projects</option><option value="own">My projects</option><option value="followed">Following</option></select></label><label>Project stage<select id="stage" aria-label="Project stage"><option value="">Every stage</option>${stages.map(s=>`<option>${s}</option>`).join('')}</select></label><button id="archived">Show archived</button></div><p id="count"></p><div class="layout"><section id="cards" aria-label="Project collection"></section><section id="detail" aria-label="Project details"></section></div><form id="editor" hidden><h3 id="editor-title">New project</h3><label>Project name<input name="name" required maxlength="200"></label><label>Ownership<select name="ownership" aria-label="Ownership"><option value="own">My project</option><option value="followed">Followed external project</option></select></label><label>Stage<select name="stage" aria-label="Stage">${stages.map(s=>`<option>${s}</option>`).join('')}</select></label><label>Goal<textarea name="goal" maxlength="10000"></textarea></label><label>Next actions<textarea name="next" maxlength="10000"></textarea></label><label>Blockers<textarea name="blockers" maxlength="10000"></textarea></label><label>Decisions<textarea name="decisions" maxlength="10000"></textarea></label><label>Resources and inspiration<textarea name="resources" maxlength="10000"></textarea></label><label>Official source URL<input name="source" type="url" maxlength="2000"></label><label>Observed version<input name="version" maxlength="200"></label><label>Release source URL<input name="release" type="url" maxlength="2000"></label><button type="submit">Save project</button><button type="button" id="cancel">Cancel</button></form><footer>Private in this browser. Export separately for backup. Followed projects are manually recorded references, not automatic polling or external social follows. Versions are your observations, not a claim of latest release. Use one editing tab. Import adds missing IDs, refuses conflicts and is limited to 100 projects / 16 MiB; nothing is silently replaced. Project continuity notes remain separate and untouched.</footer></div>`;
 const css=document.createElement('link');css.rel='stylesheet';css.href=new URL('./style.css',import.meta.url);root.prepend(css);
 const $=s=>root.querySelector(s),form=$('#editor'),notice=$('#notice');const fields=['name','ownership','stage','goal','next','blockers','decisions','resources','source','version','release'];
 const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
 const button=(label,fn)=>{const b=el('button',label);b.type='button';b.onclick=fn;return b;};
 function save(next){data=next;let saved=false;try{saved=setState?.(data)===true;}catch{}notice.textContent=saved?'Saved in this browser. Export a backup.':'Not saved. Keep this page open and export your draft before leaving.';render();}
 function edit(id){if(disposed||!data)return;editing=id;form.reset();const r=data.entries.find(p=>p.id===id)?.revisions.at(-1);for(const k of fields)form.elements[k].value=r?.[k]??(k==='ownership'?'own':k==='stage'?'idea':'');$('#editor-title').textContent=id?'Edit project':'New project';form.hidden=false;form.elements.name.focus();}
 function cancel(){editing=null;form.reset();form.hidden=true;$('#new').focus();}
 function render(){if(disposed||!data)return;const cards=$('#cards');cards.replaceChildren();const rows=browse(data,{query:search,ownership,stage,archived});$('#count').textContent=`${rows.length} visible · ${data.entries.filter(p=>!p.archived).length} active projects`;
  for(const p of rows){const r=p.revisions.at(-1),card=el('article');card.className='project-card';card.dataset.project=p.id;card.append(el('span',`${r.ownership==='own'?'OWN PROJECT':'FOLLOWING'} · ${r.stage.toUpperCase()}`),el('h3',r.name),el('p',r.goal||'A new idea waiting to take shape.'));const open=button('Open project',()=>{selected=p.id;render();$('#detail h3')?.focus();});open.setAttribute('aria-label','Open '+r.name);card.append(open);cards.append(card);}
  if(!rows.length)cards.append(el('p','No projects match. Capture an idea or adjust your filters.'));
  const detail=$('#detail');detail.replaceChildren();const p=rows.find(p=>p.id===selected);if(!p){detail.append(el('h3','Make room for the ambitious.'),el('p','Choose a project to explore its goals, decisions, next actions and source history.'));return;}
  const r=p.revisions.at(-1),title=el('h3',r.name);title.tabIndex=-1;detail.append(title,el('p',`${r.ownership==='own'?'Your project':'Followed project'} · ${r.stage}`));
  for(const [k,label] of [['goal','Goal'],['next','Next actions'],['blockers','Blockers'],['decisions','Decisions'],['resources','Resources and inspiration'],['version','Observed version']]){detail.append(el('h4',label),el('p',r[k]||'Not recorded'));}
  for(const [k,label] of [['source','Official source'],['release','Release reference']])if(r[k]){const a=el('a',label+' ↗');a.href=r[k];a.target='_blank';a.rel='noopener noreferrer';detail.append(a);}
  detail.append(button('Edit project',()=>edit(p.id)),button(p.archived?'Restore project':'Archive project',()=>{save(archive(data,p.id));$('#archived').focus();}));const history=el('details');history.append(el('summary',`${p.revisions.length} saved revision(s)`));for(const rev of [...p.revisions].reverse())history.append(el('pre',JSON.stringify(rev,null,2)));detail.append(history);const compareHost=el('div');detail.append(compareHost);import('./compare.mjs').then(({mountComparison})=>{if(!disposed&&compareHost.isConnected)mountComparison(compareHost,p);}).catch(()=>{if(!disposed&&compareHost.isConnected)compareHost.textContent='Optional revision comparison unavailable; project history remains usable.';});
 }
 $('#new').onclick=()=>edit(null);$('#cancel').onclick=cancel;
 form.onsubmit=e=>{e.preventDefault();if(!data||disposed)return;try{const input=Object.fromEntries(fields.map(k=>[k,form.elements[k].value]));const id=editing||crypto.randomUUID();const next=change(data,id,input);selected=id;save(next);cancel();}catch(e){notice.textContent=e.message;}};
 $('#ownership').onchange=e=>{ownership=e.target.value;render();};$('#stage').onchange=e=>{stage=e.target.value;render();};$('#archived').onclick=()=>{archived=!archived;$('#archived').textContent=archived?'Show active':'Show archived';render();};
 $('#export').onclick=()=>{if(!data||disposed)return;const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));urls.add(url);const a=el('a');a.href=url;a.download='athena-projects.json';a.click();};
 $('#import').onchange=async e=>{const file=e.target.files?.[0],token=++generation;e.target.value='';if(!file||!data||disposed)return;try{if(file.size>MAX_IMPORT_BYTES)throw Error('Backup exceeds 16 MiB');const incoming=parseBackup(new Uint8Array(await file.arrayBuffer()));if(disposed||token!==generation)return;const merged=mergeBackup(data,incoming);save(merged.data);notice.textContent=`Imported ${merged.added}; retained ${merged.unchanged} identical projects. `+notice.textContent;}catch(e){if(!disposed&&token===generation)notice.textContent='Import refused; existing projects unchanged. '+e.message;}};
 if(!data){notice.textContent=failure;for(const n of root.querySelectorAll('input,select,button,textarea'))n.disabled=true;}else{notice.textContent='Ready. Nothing is sent to a provider.';render();}
 function unmount(){if(disposed)return;disposed=true;generation++;for(const url of urls)URL.revokeObjectURL(url);root.replaceChildren();signal?.removeEventListener('abort',unmount);}
 function setTheme(t){container.dataset.theme=t==='light'?'light':'dark';}setTheme(theme);signal?.addEventListener('abort',unmount,{once:true});if(signal?.aborted)unmount();return {ready:!!data,unmount,setTheme,setSearch(q){search=String(q);render();}};
}
